import{c as i,U as s,h as e,l}from"./chunks/framework.C0iWzFTI.js";const t="/blog/assets/image_20250224205358.DNwmJqpw.jpg",p="/blog/assets/image_20250224205359.BXWqMpOn.jpg",n="/blog/assets/image-20250223231538742.uvbZpOYB.png",m=JSON.parse('{"title":"唯一ID","description":"场景的唯一 ID 生成算法","frontmatter":{"title":"唯一ID","description":"场景的唯一 ID 生成算法","date":false,"lastUpdated":false,"tag":["分布式"]},"headers":[],"relativePath":"5-分布式系列/1-唯一ID.md","filePath":"5-分布式系列/1-唯一ID.md"}'),r={name:"5-分布式系列/1-唯一ID.md"};function d(o,a,h,D,c,u){return s(),e("div",null,a[0]||(a[0]=[l(`<h1 id="唯一id" tabindex="-1">唯一ID <a class="header-anchor" href="#唯一id" aria-label="Permalink to &quot;唯一ID&quot;">​</a></h1><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p>在业务开发，会存在大量的场景使用唯一ID来进行标识，对于一个唯一ID，特性如下：</p><ul><li>全局唯一：必须保证生成的ID是全局唯一的</li><li>有序性：生成的ID需要按照某种规则是有序的，防止插入数据库时出现页分裂的问题</li><li>安全性：不暴露系统和业务的信息</li></ul><h2 id="二、uuid" tabindex="-1">二、UUID <a class="header-anchor" href="#二、uuid" aria-label="Permalink to &quot;二、UUID&quot;">​</a></h2><p>生成唯一ID，其中最为有效的方式就是通过 UUID 来获取，并且这种方式重复的概率非常低，在这种情况之下每个 Web 系统都含有一个ID生成器负责独立的生成ID。</p><p>但是 ID 并不能随时间增长，ID 可能也并不是纯数字的。如果采用这种方式作为数据库的主键就会造成页分裂的问题，影响插入的效率。</p><p>对于 UUID 的使用方式就比较简单了, jdk 的包里面已经提供了：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> java.util.UUID;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> UUID.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">randomUUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="三、自增id" tabindex="-1">三、自增ID <a class="header-anchor" href="#三、自增id" aria-label="Permalink to &quot;三、自增ID&quot;">​</a></h2><p>这个方法的核心就是利用数据库的自增ID来实现唯一ID，强依赖于数据库，当 DB 不可用时，整个系统就会处于不可用的状态，并且 ID 的生成效率依赖于数据库的读写性能。除了采用数据库之外，还可以采用 Redis 的 incr 命令来实现。</p><p>这两种方式虽然能够生成唯一ID，但是对于数据库和Redis的压力比较大。</p><p>针对于这种方案，可以进行如下的优化：</p><ul><li>批量生成：服务启动时，一次性生成一批次的 ID，放在内存之中，直接从内存中返回即可</li><li>水平拆分：多个分片，不同的初始值，相同的步长，即第一个分片 1,3,5,7,9..... , 第二个分片 2,4,6,8,10...</li></ul><h2 id="四、数据库的号段模式" tabindex="-1">四、数据库的号段模式 <a class="header-anchor" href="#四、数据库的号段模式" aria-label="Permalink to &quot;四、数据库的号段模式&quot;">​</a></h2><p>号段模式，可以理解为批量从数据库获取一部分ID，然后存在内存之中，获取 ID 的时候直接从内存之中返回即可。比如有两台服务器，第一台服务器申请到的号段是：[1,1000]，第二个服务器申请到的号段是：[1001,2000]，第一台服务器获取ID的时候，就从1开始递增，直到申请到的号段使用完成。通过这种方式，可以大大减少数据库的使用压力。</p><p>接下来，我们就来看一下美团 Leaf-segment 方案。对于美团的方案，其实就是基于数据库批量生成，其对应的流程如下：在数据库之中建立一张表，用来表示不同的业务当前使用到的最大ID，以及每次申请的步长，当我们申请 ID 的时候，只需要执行 <code>update XX set max_id = max_id + step</code> ，当 update 成功的时候，就说明申请到了 <strong>[max_id, max_id + step]</strong> 范围的号段</p><p><img src="`+t+'" alt=""></p><p>使用这种方式，有如下的缺点：</p><ul><li>ID号码不够随机，能够泄露发号数量的信息，不太安全。</li><li>当号段使用完之后，去再次去申请号段，会有阻塞，并且会耗时在数据库的 IO</li><li>DB宕机会造成整个系统不可用。</li></ul><p>为了解决问题二，采用双buffer的方式，服务内部有两个号段缓存区 segment。当前号段已下发10%时，如果下一个号段未更新，则另启一个更新线程去更新下一个号段。当前号段全部下发完后，如果下个号段准备好了则切换到下个号段为当前segment接着下发，循环往复。</p><p><img src="'+p+'" alt=""></p><p>但是，我看了一下 GitHub 的代码，不知道是否维护？</p><h2 id="五、雪花算法" tabindex="-1">五、雪花算法 <a class="header-anchor" href="#五、雪花算法" aria-label="Permalink to &quot;五、雪花算法&quot;">​</a></h2><p>对于雪花算法，由 64 位组成，构成图如下：</p><p><img src="'+n+'" alt="image-20250223231538742"></p><p>其中，这几部分的含义如下：</p><ul><li>符号位：1 位，始终作为数字 0</li><li>时间戳：41 位</li><li>数据中心：5 位，最多可以有 32 个数据中心</li><li>机器ID：5位，每个数据中心最多可以有 32 个机器</li><li>序列号：12 位，对于某个机器或者进程，每生成一个 ID，序列号就加一，这个数字每毫秒开始都被重置为 0</li></ul><p>对于 数据中心ID 和 机器ID 通常在起始阶段就选好了，一旦系统运行起来，这两个部分都是固定的，对于时间戳和序列号在运行后生效。</p><p>这种方案的<strong>优势</strong>在于：本次生成，没有网络开销，性能较高，整体呈增长趋势。<strong>劣势</strong>在于时钟回拨问题。</p><p>为了解决时钟回拨问题，可以采用如下方案：</p><ul><li>将 ID 生成交给少量服务器，关闭这些服务器的时钟回拨能力，这样做对于ID的生成就不是本地了，而是需要调用对应的接口来获取唯一ID</li></ul>',32)]))}const g=i(r,[["render",d]]);export{m as __pageData,g as default};
